CREATE TABLE IF NOT EXISTS schema_migrations(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, phone text NOT NULL UNIQUE, password_hash text, role text NOT NULL DEFAULT 'student' CHECK(role IN ('student','admin','super_admin')), status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended','anonymized')), status_reason text, institution text NOT NULL DEFAULT '', course_id text, level text NOT NULL DEFAULT '', avatar_key text, permissions jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(id text PRIMARY KEY, user_id text REFERENCES users(id), csrf text NOT NULL, user_agent text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE password_resets(id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL, used_at timestamptz);
CREATE TABLE courses(id text PRIMARY KEY, name text NOT NULL UNIQUE, description text NOT NULL DEFAULT '', icon text NOT NULL DEFAULT 'book', created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE users ADD CONSTRAINT user_course FOREIGN KEY(course_id) REFERENCES courses(id);
CREATE TABLE units(id text PRIMARY KEY, course_id text NOT NULL REFERENCES courses(id), name text NOT NULL, code text NOT NULL, UNIQUE(course_id,code));
CREATE TABLE assessment_series(id text PRIMARY KEY, name text NOT NULL, year integer NOT NULL, status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','closed','deleting','deleted')), UNIQUE(name,year));
CREATE TABLE taxonomy(id text PRIMARY KEY, kind text NOT NULL CHECK(kind IN ('level','body','type')), name text NOT NULL, UNIQUE(kind,name));
CREATE TABLE resources(id text PRIMARY KEY, title text NOT NULL, description text NOT NULL DEFAULT '', course_id text NOT NULL REFERENCES courses(id), unit_id text NOT NULL REFERENCES units(id), series_id text NOT NULL REFERENCES assessment_series(id), level text NOT NULL, body text NOT NULL DEFAULT 'Institution', type text NOT NULL, price_minor integer NOT NULL CHECK(price_minor>=0), year integer NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','archived','deleted')), file_key text, preview_key text, file_size integer NOT NULL DEFAULT 0, pages integer NOT NULL DEFAULT 0, demo boolean NOT NULL DEFAULT false, created_by text REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX resources_catalogue ON resources(status,course_id,series_id,year);
CREATE INDEX resources_unit ON resources(unit_id);
CREATE TABLE resource_versions(id text PRIMARY KEY, resource_id text NOT NULL REFERENCES resources(id), file_key text NOT NULL, file_size integer NOT NULL, created_by text REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE bundles(id text PRIMARY KEY, title text NOT NULL, description text NOT NULL DEFAULT '', price_minor integer NOT NULL CHECK(price_minor>=0), active boolean NOT NULL DEFAULT true);
CREATE TABLE bundle_items(bundle_id text REFERENCES bundles(id), resource_id text REFERENCES resources(id), PRIMARY KEY(bundle_id,resource_id));
CREATE TABLE wishlists(user_id text REFERENCES users(id), resource_id text REFERENCES resources(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,resource_id));
CREATE TABLE cart_items(user_id text REFERENCES users(id), item_id text NOT NULL, kind text NOT NULL CHECK(kind IN ('resource','bundle')), PRIMARY KEY(user_id,item_id,kind));
CREATE TABLE orders(id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), amount_minor integer NOT NULL CHECK(amount_minor>=0), currency text NOT NULL DEFAULT 'KES', status text NOT NULL DEFAULT 'initiated' CHECK(status IN ('initiated','pending','completed','failed','cancelled','reversed','needs_review')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX orders_user ON orders(user_id,created_at);
CREATE TABLE order_items(order_id text REFERENCES orders(id), resource_id text REFERENCES resources(id), title text NOT NULL, price_minor integer NOT NULL CHECK(price_minor>=0), PRIMARY KEY(order_id,resource_id));
CREATE TABLE payment_attempts(id text PRIMARY KEY, order_id text NOT NULL REFERENCES orders(id), tracking_id text UNIQUE, redirect_url text, state text NOT NULL DEFAULT 'initiated', failure text, created_at timestamptz NOT NULL DEFAULT now(), checked_at timestamptz);
CREATE TABLE payment_events(id text PRIMARY KEY, attempt_id text REFERENCES payment_attempts(id), state text NOT NULL, amount_minor integer, currency text, reference text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE entitlements(user_id text REFERENCES users(id), resource_id text REFERENCES resources(id), order_id text REFERENCES orders(id), state text NOT NULL DEFAULT 'active', purchased_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,resource_id));
CREATE TABLE receipts(id text PRIMARY KEY, order_id text NOT NULL UNIQUE REFERENCES orders(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE paper_requests(id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), course_id text REFERENCES courses(id), unit text NOT NULL, details text NOT NULL, status text NOT NULL DEFAULT 'open', resource_id text REFERENCES resources(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications(id text PRIMARY KEY, title text NOT NULL, message text NOT NULL, priority text NOT NULL DEFAULT 'normal', link text NOT NULL DEFAULT '/account/notifications', created_by text REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notification_recipients(notification_id text REFERENCES notifications(id), user_id text REFERENCES users(id), read_at timestamptz, PRIMARY KEY(notification_id,user_id));
CREATE INDEX recipient_unread ON notification_recipients(user_id,read_at);
CREATE TABLE support_tickets(id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), subject text NOT NULL, resource_id text REFERENCES resources(id), status text NOT NULL DEFAULT 'open', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ticket_messages(id text PRIMARY KEY, ticket_id text NOT NULL REFERENCES support_tickets(id), user_id text NOT NULL REFERENCES users(id), message text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE download_logs(id text PRIMARY KEY, user_id text REFERENCES users(id), resource_id text REFERENCES resources(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE deletion_jobs(id text PRIMARY KEY, series_id text NOT NULL REFERENCES assessment_series(id), reason text NOT NULL, execute_after timestamptz NOT NULL, status text NOT NULL DEFAULT 'scheduled' CHECK(status IN ('scheduled','running','cancelled','completed')), created_by text NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE deletion_resources(job_id text REFERENCES deletion_jobs(id), resource_id text REFERENCES resources(id), PRIMARY KEY(job_id,resource_id));
CREATE TABLE deletion_recipients(job_id text REFERENCES deletion_jobs(id), user_id text REFERENCES users(id), PRIMARY KEY(job_id,user_id));
CREATE TABLE jobs(id text PRIMARY KEY, kind text NOT NULL, payload jsonb NOT NULL, state text NOT NULL DEFAULT 'pending', attempts integer NOT NULL DEFAULT 0, run_after timestamptz NOT NULL DEFAULT now(), locked_at timestamptz, last_error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX jobs_due ON jobs(state,run_after);
CREATE TABLE audit_logs(id text PRIMARY KEY, actor_id text REFERENCES users(id), action text NOT NULL, target text NOT NULL DEFAULT '', detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE settings(key text PRIMARY KEY, value jsonb NOT NULL);
